-- calc_policies_name
-- Field: Policies.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_policies_name(p_policy_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(policy_id, '') FROM policies WHERE policy_id = p_policy_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_policies_count_of_covered_claimants
-- Field: Policies.CountOfCoveredClaimants
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_policies_count_of_covered_claimants(p_policy_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM claimants WHERE policy = (SELECT NULLIF(policy_id, '') FROM policies WHERE policy_id = p_policy_id)))::integer;
$$ LANGUAGE sql STABLE;

